<?php $orders=$orders??[]; ?>
<section class="ca-card"><div class="ca-card-head"><div><h2>Historial de compras</h2><p class="ca-note mb-0"><?= (int)($totalOrders??0) ?> pedidos registrados</p></div></div>
<?php if(!$orders): ?><div class="ca-empty"><i class="fa-solid fa-box-open"></i><h3 class="h6 fw-bold text-dark">Aún no hay pedidos</h3><p>Visita nuestra tienda y encuentra tus favoritos.</p><a class="ca-button" href="<?= APP_URL ?>/tienda">Ir a la tienda</a></div>
<?php else: ?><div class="ca-table-wrap"><table><thead><tr><th>Pedido</th><th>Fecha</th><th>Productos</th><th>Tipo entrega</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><strong><?= htmlspecialchars($o['order_number'],ENT_QUOTES,'UTF-8') ?></strong></td><td><?= date('d/m/Y H:i',strtotime($o['created_at'])) ?></td><td><?= (int)$o['item_quantity'] ?></td><td><?= ($o['fulfillment_type']??'pickup')==='delivery'?'Domicilio':'Recoger en tienda' ?></td><td><strong><?= $caMoney($o['total']) ?></strong></td><td><span class="ca-status ca-status--<?= htmlspecialchars($o['status'],ENT_QUOTES,'UTF-8') ?>"><?= htmlspecialchars($caStatus($o['status']),ENT_QUOTES,'UTF-8') ?></span></td><td><a class="ca-link" href="<?= APP_URL ?>/mi-cuenta/pedido?id=<?= (int)$o['id'] ?>">Ver detalle</a></td></tr><?php endforeach; ?></tbody></table></div>
<?php if(($pages??1)>1): ?><div class="d-flex justify-content-between align-items-center pt-3"><span class="ca-note">Página <?= (int)$page ?> de <?= (int)$pages ?></span><div class="d-flex gap-2"><?php if($page>1): ?><a class="ca-button ca-button--light" href="?page=<?= $page-1 ?>">Anterior</a><?php endif; ?><?php if($page<$pages): ?><a class="ca-button" href="?page=<?= $page+1 ?>">Siguiente</a><?php endif; ?></div></div><?php endif; ?>
<?php endif; ?></section>